SELECT page_id, shop_id, page_name, page_data, page_type, page_start, create_time, page_is_index FROM ${database.prefix.userms}hou_base_shop_modularizationd WHERE 1 =1
and page_is_index = #{param.pageIsIndex}
and page_name LIKE CONCAT('%',#{param.pageName},'%')
and page_id = #{param.pageId}
and shop_id = #{param.shopId}
and page_is_index = #{param.pageIsIndex}
ORDER BY create_time desc
